<div class="list-footer"><span><?= $total ? (($page-1)*20+1).'–'.min($page*20,$total).' of '.$total : '0' ?> records · Page <?= $page ?> of <?= $pages ?></span><nav class="pagination" aria-label="Admin pages"><?php if($page>1): ?><a href="<?= e(url($listPath.'?'.http_build_query(array_merge($filters,['page'=>$page-1])))) ?>">← Previous</a><?php endif; ?><?php if($page<$pages): ?><a href="<?= e(url($listPath.'?'.http_build_query(array_merge($filters,['page'=>$page+1])))) ?>">Next →</a><?php endif; ?></nav></div>
